sksl:
uniform shader image;
uniform float2 size;
uniform float4 screen;
uniform float time;
uniform float2 center;
uniform float strength;
uniform float radius;
uniform float aberration;
uniform float centerChannel;
float2 spin(float2 d, float a, float z) {
    return float2(cos(a) * d.x - sin(a) * d.y, sin(a) * d.x + cos(a) * d.y) * z;
}
half4 main(float2 coord) {
    float2 c = center * size;
    float2 d = coord - c;
    float r = max(radius, 0.001);
    float x = clamp(1.0 - length(d) / (r * 1.0435 * min(screen.z, screen.w)), 0.0, 1.0);
    float s = max(strength, 0.0);
    float fall = pow(x, 1.94);
    float turn = 42.76 * pow(s, 3.025) / (r * r) * fall;
    float pull = 1.575 * s * fall;
    if (turn <= 0.0 && pull <= 0.0) return image.eval(coord);
    float3 k = max(1.0 + aberration * (float3(0.0, 1.0, 2.0) - centerChannel), float3(0.0));
    float4 sum = float4(0.0);
    float3 alpha = float3(0.0);
    for (int i = 0; i < 48; i++) {
        float t = pow(float(i) / 47.0, 1.594);
        if (aberration > 0.0) {
            float3 a = -turn * t * k;
            float3 z = 1.0 - pull * t * k;
            half4 pr = image.eval(c + spin(d, a.r, z.r));
            half4 pg = image.eval(c + spin(d, a.g, z.g));
            half4 pb = image.eval(c + spin(d, a.b, z.b));
            sum.rgb += float3(pr.r, pg.g, pb.b);
            alpha += float3(pr.a, pg.a, pb.a);
        } else {
            half4 p = image.eval(c + spin(d, -turn * t, 1.0 - pull * t));
            sum += float4(p);
        }
    }
    float a = aberration > 0.0 ? (alpha.r + alpha.g + alpha.b) / 144.0 : sum.a / 48.0;
    return half4(half3(min(sum.rgb / 48.0, float3(a))), half(a));
}
